  `transaction_type` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recipient` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `merchant` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(14,2) NOT NULL,
  `transaction_time` datetime NOT NULL DEFAULT current_timestamp(),
  `raw_timestamp` bigint(20) UNSIGNED NOT NULL,
  `Time` double DEFAULT 0,
  `risk_score` int(11) DEFAULT NULL,
  `is_fraudulent` tinyint(1) DEFAULT 0,
  `risk_level` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model_scores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`model_scores`)),
  `explanation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`explanation`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `step` double DEFAULT NULL,
  `time_hour` int(11) DEFAULT NULL,
  `amount_z` double DEFAULT NULL,
  `oldbalanceOrg` double DEFAULT NULL,
  `newbalanceOrig` double DEFAULT NULL,
  `oldbalanceDest` double DEFAULT NULL,
  `newbalanceDest` double DEFAULT NULL,
  `orig_amount_mean` double DEFAULT NULL,
  `orig_amount_std` double DEFAULT NULL,
  `time_since_prev` double DEFAULT NULL,
  `tx_count_24h` int(11) DEFAULT NULL,
  `is_unusual_amount` tinyint(1) DEFAULT 0,
  `merchant_risk` decimal(10,4) DEFAULT 0.0000,
  `account_age_days` int(11) DEFAULT 0,
  `auth_failures` int(11) DEFAULT 0,
  `type_PAYMENT` tinyint(1) DEFAULT 0,
  `type_CASH_OUT` tinyint(1) DEFAULT 0,
  `type_DEBIT` tinyint(1) DEFAULT 0,
  `type_TRANSFER` tinyint(1) DEFAULT 0,
  `merchant_cat_grocery` tinyint(1) DEFAULT 0,
  `merchant_cat_restaurant` tinyint(1) DEFAULT 0,
  `merchant_cat_retail` tinyint(1) DEFAULT 0,
  `merchant_cat_travel` tinyint(1) DEFAULT 0,
  `merchant_cat_utilities` tinyint(1) DEFAULT 0,
  `country_CN` tinyint(1) DEFAULT 0,
  `country_DE` tinyint(1) DEFAULT 0,
  `country_FR` tinyint(1) DEFAULT 0,
  `country_GB` tinyint(1) DEFAULT 0,
  `country_IN` tinyint(1) DEFAULT 0,
  `country_JP` tinyint(1) DEFAULT 0,
  `country_NG` tinyint(1) DEFAULT 0,
  `country_RU` tinyint(1) DEFAULT 0,
  `country_US` tinyint(1) DEFAULT 0,
  `feature_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`feature_snapshot`)),
  `model_reason` text COLLATE utf8mb4_unicode_ci DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

